from __future__ import annotations

import sympy as sp
from sympy.core.relational import Relational

from .._zero_testing import certified_equal
from .atoms import normalize_atoms


def _merge_point_with_strict_ray(expr: sp.Expr) -> sp.Expr:
    """Merge simple ``Eq(x, a) | x > a``/``Eq(x, a) | x < a`` patterns.

    ``simplify_logic`` treats relational atoms propositionally, so
    it does not know that a strict ray plus its endpoint is a closed ray. This
    small semantic cleanup keeps QE output compact without calling scalar
    ``sp.simplify`` on Boolean formulas.
    """

    if not isinstance(expr, sp.Or) or len(expr.args) != 2:
        return expr
    left, right = expr.args
    pairs = ((left, right), (right, left))
    for eq, rel in pairs:
        if not isinstance(eq, sp.Equality):
            continue
        for var, value in ((eq.lhs, eq.rhs), (eq.rhs, eq.lhs)):
            if not isinstance(var, sp.Symbol) or getattr(value, "has", lambda *_: False)(var):
                continue
            if isinstance(rel, sp.StrictGreaterThan):
                if rel.lhs == var and certified_equal(rel.rhs, value) is True:
                    return var >= value
                if rel.rhs == var and certified_equal(rel.lhs, value) is True:
                    return var <= value
            if isinstance(rel, sp.StrictLessThan):
                if rel.lhs == var and certified_equal(rel.rhs, value) is True:
                    return var <= value
                if rel.rhs == var and certified_equal(rel.lhs, value) is True:
                    return var >= value
    return expr


def simplify_boolean_form(expr: sp.Expr, *, form: str = "dnf") -> sp.Expr:
    """Simplify Boolean structure in DNF/CNF while treating relations atomically."""

    expr = normalize_atoms(expr)
    relations = tuple(sorted(expr.atoms(Relational), key=sp.default_sort_key))
    if not relations:
        try:
            return sp.simplify_logic(expr, form=form, deep=False)
        except (TypeError, ValueError, NotImplementedError, AttributeError):
            return expr
    symbols = tuple(sp.Dummy(f"rel_{index}", boolean=True) for index in range(len(relations)))
    forward = dict(zip(relations, symbols, strict=True))
    reverse = dict(zip(symbols, relations, strict=True))
    propositional = expr.xreplace(forward)
    try:
        simplified = sp.simplify_logic(propositional, form=form, deep=False)
    except (TypeError, ValueError, NotImplementedError, AttributeError):
        simplified = propositional
    return simplified.xreplace(reverse)


def simplify_boolean(expr: sp.Expr) -> sp.Expr:
    """Simplify Boolean structure without recursively simplifying relations."""

    return _merge_point_with_strict_ray(simplify_boolean_form(expr, form="dnf"))


__all__ = ["simplify_boolean", "simplify_boolean_form"]
